class Solution:
    def nextMirror(self, code: str) -> str:
        n = len(code)
        half = code[:n // 2]
        count = [0] * 10
        for ch in half:
            count[ord(ch) - 48] += 1
        buf = []
        def build():
            if len(buf) == len(half):
                s = "".join(buf)
                return s if s > half else None
            for d in range(10):
                if count[d]:
                    count[d] -= 1
                    buf.append(chr(48 + d))
                    found = build()
                    buf.pop()
                    count[d] += 1
                    if found:
                        return found
            return None
        left = build()
        if left is None:
            return ""
        return left + code[n // 2:(n + 1) // 2] + left[::-1]

