class Solution {
    private int[] count = new int[10];
    private char[] buf;
    private String half;

    public String nextMirror(String code) {
        int n = code.length();
        half = code.substring(0, n / 2);
        for (char ch : half.toCharArray()) count[ch - '0']++;
        buf = new char[half.length()];
        if (!build(0)) return "";
        String left = new String(buf);
        return left + code.substring(n / 2, (n + 1) / 2) + new StringBuilder(left).reverse();
    }

    private boolean build(int pos) {
        if (pos == buf.length) return new String(buf).compareTo(half) > 0;
        for (int d = 0; d < 10; d++) {
            if (count[d] == 0) continue;
            count[d]--;
            buf[pos] = (char) ('0' + d);
            boolean found = build(pos + 1);
            count[d]++;
            if (found) return true;
        }
        return false;
    }
}

