char* nextMirror(char* code) {
    int n = strlen(code);
    h = n / 2;
    half = calloc(h + 1, 1);
    memcpy(half, code, h);
    buf = calloc(h + 1, 1);
    memset(count, 0, sizeof count);
    for (int i = 0; i < h; i++) count[half[i] - '0']++;
    char* out = calloc(n + 1, 1);
    if (build(0)) {
        memcpy(out, buf, h);
        if (n % 2) out[h] = code[h];
        for (int i = 0; i < h; i++) out[n - 1 - i] = buf[i];
    }
    free(half);
    free(buf);
    return out;
}

