class Solution:
    def nextMirror(self, code: str) -> str:
        n = len(code)
        h = list(code[:n // 2])
        i = len(h) - 2
        while i >= 0 and h[i] >= h[i + 1]:
            i -= 1
        if i < 0:
            return ""
        j = len(h) - 1
        while h[j] <= h[i]:
            j -= 1
        h[i], h[j] = h[j], h[i]
        h[i + 1:] = reversed(h[i + 1:])
        left = "".join(h)
        return left + code[n // 2:(n + 1) // 2] + left[::-1]

