class Solution {
    public String nextMirror(String code) {
        int n = code.length();
        char[] h = code.substring(0, n / 2).toCharArray();
        int i = h.length - 2;
        while (i >= 0 && h[i] >= h[i + 1]) i--;
        if (i < 0) return "";
        int j = h.length - 1;
        while (h[j] <= h[i]) j--;
        char t = h[i]; h[i] = h[j]; h[j] = t;
        for (int a = i + 1, b = h.length - 1; a < b; a++, b--) { t = h[a]; h[a] = h[b]; h[b] = t; }
        String left = new String(h);
        return left + code.substring(n / 2, (n + 1) / 2) + new StringBuilder(left).reverse();
    }
}

