class Solution {
public:
    string nextMirror(string& code) {
        int n = code.size();
        string h = code.substr(0, n / 2);
        int i = (int) h.size() - 2;
        while (i >= 0 && h[i] >= h[i + 1]) i--;
        if (i < 0) return "";
        int j = h.size() - 1;
        while (h[j] <= h[i]) j--;
        swap(h[i], h[j]);
        reverse(h.begin() + i + 1, h.end());
        string right(h.rbegin(), h.rend());
        return h + code.substr(n / 2, n % 2) + right;
    }
};

