char* nextMirror(char* code) {
    int n = strlen(code), m = n / 2;
    char* out = calloc(n + 1, 1);
    memcpy(out, code, m);
    int i = m - 2;
    while (i >= 0 && out[i] >= out[i + 1]) i--;
    if (i < 0) { out[0] = '\0'; return out; }
    int j = m - 1;
    while (out[j] <= out[i]) j--;
    char t = out[i]; out[i] = out[j]; out[j] = t;
    for (int a = i + 1, b = m - 1; a < b; a++, b--) { t = out[a]; out[a] = out[b]; out[b] = t; }
    if (n % 2) out[m] = code[m];
    for (int k = 0; k < m; k++) out[n - 1 - k] = out[k];
    return out;
}
